// Написан autotest-writer вручную (обрыв сети через route — генератор не умеет). spec: .qa/e2e/specs/gifts.md 4.3; кейс .qa/tests/gifts/GIFT-13 (AC 7).
// Запись настроек обрывается (route abort) — данные не меняются; на всякий случай в finally состояние тумблера возвращается.
// Текст ошибки «השינוי לא נשמר…» — из комментария программиста (#f023a0); на живой странице не проверен — проверить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import { saveSession } from '../_shared/session';
import { phone, openNotificationSettings, settingSwitch, switchState, setSwitch } from './gifts-helpers';

const LABEL = 'התראה על מתנה חדשה';
const isWrite = (url: string, method: string) => url.includes('/rest/v1/') && !['GET', 'HEAD', 'OPTIONS'].includes(method);

test.describe('Подарки: ошибка сохранения настроек', () => {
  test.describe.configure({ timeout: 150_000 });

  test('Ошибка сохранения тумблера (обрыв сети): «השינוי לא נשמר…», тумблер возвращается @iphone @data (#f023a0)', async ({ asUser }) => {
    const p = await asUser('new02');
    let before: boolean | undefined;
    try {
      await phone(p);
      await openNotificationSettings(p);
      const sw = settingSwitch(p, LABEL);
      await expect(sw).toBeVisible();
      before = await switchState(sw);

      await p.route('**/rest/v1/**', (route) => (isWrite(route.request().url(), route.request().method()) ? route.abort('internetdisconnected') : route.continue()));
      await sw.click();
      await expect(p.getByText(/השינוי לא נשמר/)).toBeVisible({ timeout: 15_000 });
      await expect(sw, 'тумблер вернулся').toHaveAttribute('aria-checked', String(before));
      await p.unroute('**/rest/v1/**');

      await openNotificationSettings(p);
      await expect(settingSwitch(p, LABEL)).toHaveAttribute('aria-checked', String(before));
    } finally {
      await p.unroute('**/rest/v1/**').catch(() => {});
      if (before !== undefined) await openNotificationSettings(p).then(() => setSwitch(p, LABEL, before!)).catch(() => {});
      await saveSession(p, 'new02');
    }
  });
});
